def true_name(cite):
    parts = [p.strip().lower() for p in cite.split("|")]
    return "-".join(parts)
print(true_name("Higgins | 2026 | Archive Intelligence"))
assert true_name("Higgins | 2026 | Archive Intelligence") == "higgins-2026-archive intelligence"

stones = {"old": "new", "a": "b", "b": "a"}
def walk(start):
    trail, cur = [], start
    while cur in stones:
        if cur in trail: return "LOOP"
        trail.append(cur); cur = stones[cur]
    return cur
print(walk("old"), walk("a"))
assert (walk("old"), walk("a")) == ("new", "LOOP")

threads = {"a": ["b"], "b": ["c"], "c": []}
def ripples(start):
    wet, wave = set(), [start]
    while wave:
        n = wave.pop()
        for m in threads[n]:
            if m not in wet: wet.add(m); wave.append(m)
    return wet
print("ripples from a:", ripples("a"))
assert ripples("a") == {"b", "c"}

forward = {"a": ["b"], "b": []}
backward = {n: [] for n in forward}
for s, ts in forward.items():
    for t in ts: backward[t].append(s)
print("threads into b:", backward["b"])
assert backward["b"] == ["a"]

def kin(a, b):
    ta, tb = set(a.lower().split()), set(b.lower().split())
    return len(ta & tb)/len(ta | tb)
print("kinship:", round(kin("Higgins 2026 Archive", "higgins 2026 archive"), 2))
assert kin("Higgins 2026 Archive", "higgins 2026 archive") == 1.0

tellings = {"doc-1": ["first", "second"]}
def tell(name, pin=None):
    ts = tellings[name]
    return pin if pin in ts else ts[-1]
print(tell("doc-1"), "| pinned:", tell("doc-1", "first"))
assert tell("doc-1") == "second"

